}

/* ========== INSTRUCTOR GRID ========== */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  animation: fadeInUp 0.4s ease;
}
.instructor-card:hover { border-color: var(--red); transform: translateY(-4px); }
.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-card), rgba(230,57,70,0.1));
  display: flex;
  align-items: center;
  justify-content: center;
}
.instructor-photo i {
  font-size: 4rem;
  color: var(--red);
  opacity: 0.5;
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
}
.instructor-info .location {
  color: var(--text-muted);
  font-size: 0.85rem;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.instructor-info .location i { color: var(--red); font-size: 0.9rem; }
.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--red);
  font-weight: 600;
  transition: color var(--transition);
}
.instructor-info .book-link:hover { color: #fff; }
.instructor-card.hidden { display: none; }

/* ========== FAQ ACCORDION ========== */
.faq-list { max-width: 780px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: #fff;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  text-align: left;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question i {
  font-size: 1.2rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.active .faq-question i { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p {
  padding: 0 0 24px;
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ========== DIGITAL FEATURES ========== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 32px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 40px 32px;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--red); transform: translateY(-4px); }
.feature-card .feature-icon {
  font-size: 2.2rem;
  color: var(--red);
  margin-bottom: 20px;
}
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
}
.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* ========== CTA SECTION (reusable) ========== */
.cta-section {
  text-align: center;
  padding: 80px 0;
}
.cta-section h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 28px;
}

/* ========== ANIMATIONS ========== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-utility { display: none; }
  .hamburger { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 24px;
    gap: 16px;
    border-bottom: 1px solid var(--border);
  }
  .nav-utility.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 0 24px 24px;
    gap: 12px;
  }
  .community-inner { grid-template-columns: 1fr; gap: 40px; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  section { padding: 70px 0; }
  .hero { min-height: 70vh; }
  .hero-sm { min-height: 40vh; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .btn { width: 100%; max-width: 320px; justify-content: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { width: 100%; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .carousel-btn { width: 40px; height: 40px; }
  .toggle-controls { flex-direction: column; align-items: center; }
  .toggle-btn { width: 100%; max-width: 300px; }
  .toggle-btn:first-child { border-right: 2px solid var(--border); border-bottom: none; }
  .filter-controls { gap: 8px; }
  .filter-btn { padding: 8px 16px; font-size: 0.75rem; }
  .schedule-table th, .schedule-table td { padding: 14px 16px; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .way-card { padding: 32px 24px; }
  .hero h1 { letter-spacing: 1px; }
}
