@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B71C1C;
  --bg: #111;
  --bg-card: #1a1a1a;
  --bg-card-hover: #222;
  --bg-surface: #161616;
  --text: #fff;
  --text-muted: #aaa;
  --text-dim: #777;
  --border: #2a2a2a;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --max-width: 1200px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button, input, select { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ========== TOP BAR ========== */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.5px;
}
.top-bar a {
  color: #fff;
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 600;
}

/* ========== NAV ========== */
.nav {
  background: rgba(17,17,17,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
}
.nav-logo span { color: #fff; }
.nav-links { display: flex; gap: 28px; align-items: center; }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: #fff; }
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--red);
  transition: width var(--transition);
}
.nav-links a:hover::after, .nav-links a.active::after { width: 100%; }
.nav-utility { display: flex; gap: 16px; align-items: center; }
.nav-utility a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  transition: color var(--transition);
}
.nav-utility a:hover { color: #fff; }
.btn-nav {
  background: var(--red);
  color: #fff !important;
  padding: 10px 20px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform 0.15s;
}
.btn-nav:hover { background: var(--red-dark); transform: translateY(-1px); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
}
.hamburger span {
  width: 24px;
  height: 2px;
  background: #fff;
  transition: var(--transition);
}

/* ========== HERO ========== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: linear-gradient(135deg, #111 0%, #1a0a0a 50%, #111 100%);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230,57,70,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}
.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 3px;
  margin-bottom: 20px;
}
.hero h1 .highlight { color: var(--red); }
.hero p {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 36px;
  line-height: 1.7;
}
.hero-ctas { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.hero-sm { min-height: 50vh; }
.hero-sm h1 { font-size: clamp(2rem, 5vw, 3.5rem); }

/* ========== BUTTONS ========== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 16px 36px;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.btn-primary { background: var(--red); color: #fff; }
.btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); box-shadow: 0 8px 30px rgba(230,57,70,0.3); }
.btn-outline { background: transparent; color: #fff; border: 2px solid #fff; }
.btn-outline:hover { background: #fff; color: #111; }
.btn-large { padding: 20px 48px; font-size: 1.15rem; }
.btn-sm { padding: 12px 24px; font-size: 0.85rem; }

/* ========== SECTIONS ========== */
section { padding: 100px 0; }
.section-header {
  text-align: center;
  margin-bottom: 60px;
}
.section-header h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto;
  line-height: 1.7;
}
.red-line {
  width: 60px;
  height: 3px;
  background: var(--red);
  margin: 20px auto;
}

/* ========== COMMUNITY PROMO ========== */
.community-promo {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.community-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.community-text h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 20px;
}
.community-text p {
  color: var(--text-muted);
  font-size: 1.05rem;
  line-height: 1.8;
  margin-bottom: 32px;
}
.community-visual {
  background: linear-gradient(135deg, var(--bg-card), rgba(230,57,70,0.1));
  border: 1px solid var(--border);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2rem;
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 4px;
}

/* ========== TWO WAYS ========== */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: var(--red); transform: translateY(-4px); }
.way-card .icon-wrap {
  width: 64px;
  height: 64px;
  background: rgba(230,57,70,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  font-size: 1.5rem;
  color: var(--red);
}
.way-card h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
}
.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 28px;
}

/* ========== STUDIO EXPERIENCE ========== */
.studio-exp {
  background: linear-gradient(180deg, var(--bg) 0%, #1a0a0a 50%, var(--bg) 100%);
  text-align: center;
}
.studio-exp .cta-text {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--text-muted);
  margin-bottom: 24px;
}

/* ========== FREE TRIAL ========== */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 0%, rgba(0,0,0,0.2) 100%);
  pointer-events: none;
}
.free-trial h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 4px;
  margin-bottom: 32px;
  position: relative;
}
.free-trial .btn {
  position: relative;
  background: #fff;
  color: var(--red);
}
.free-trial .btn:hover {
  background: #111;
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* ========== CAROUSEL ========== */
.carousel-section { overflow: hidden; background: var(--bg-surface); }
.carousel-wrap { position: relative; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/7;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  text-align: center;
  padding: 40px;
}
.carousel-slide h3 {
  font-family: var(--font-heading);
  font-size: 2rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 12px;
}
.carousel-slide p { color: var(--text-muted); font-size: 1.1rem; }
.carousel-slide:nth-child(1) { background: linear-gradient(135deg, #1a1a1a, rgba(230,57,70,0.15)); }
.carousel-slide:nth-child(2) { background: linear-gradient(135deg, rgba(230,57,70,0.1), #1a1a1a); }
.carousel-slide:nth-child(3) { background: linear-gradient(135deg, #1a1a1a, rgba(230,57,70,0.2)); }
.carousel-slide:nth-child(4) { background: linear-gradient(135deg, rgba(230,57,70,0.08), #1a1a1a); }
.carousel-icon {
  font-size: 4rem;
  color: var(--red);
  margin-bottom: 20px;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 52px;
  height: 52px;
  background: rgba(17,17,17,0.8);
  border: 1px solid var(--border);
  color: #fff;
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  z-index: 10;
}
.carousel-btn:hover { background: var(--red); border-color: var(--red); }
.carousel-btn.prev { left: 20px; }
.carousel-btn.next { right: 20px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  padding: 24px 0;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* ========== NEWSLETTER ========== */
.newsletter {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: 80px 0;
}
.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 12px;
}
.newsletter p {
  color: var(--text-muted);
  margin-bottom: 28px;
  line-height: 1.7;
}
.newsletter-form {
  display: flex;
  gap: 12px;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: #fff;
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form button {
  padding: 14px 28px;
  background: var(--red);
  color: #fff;
  border: none;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-msg {
  margin-top: 12px;
  font-size: 0.85rem;
  min-height: 20px;
}
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: var(--red); }

/* ========== FOOTER ========== */
.footer {
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 50px;
}
.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 20px;
  color: var(--red);
}
.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 5px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.country-select {
  padding: 10px 14px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.85rem;
  outline: none;
  width: 100%;
  margin-top: 8px;
  cursor: pointer;
}
.country-select:focus { border-color: var(--red); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer-bottom p {
  color: var(--text-dim);
  font-size: 0.8rem;
}
.footer-socials { display: flex; gap: 16px; }
.footer-socials a {
  color: var(--text-muted);
  font-size: 1.2rem;
  transition: color var(--transition);
}
.footer-socials a:hover { color: var(--red); }

/* ========== METHOD OVERVIEW ========== */
.method-overview { background: var(--bg-surface); }
.method-text {
  max-width: 750px;
  margin: 0 auto;
  text-align: center;
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.9;
}

/* ========== WEEKLY SCHEDULE ========== */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  max-width: 700px;
  margin: 0 auto;
}
.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td {
  font-size: 0.95rem;
  color: var(--text-muted);
}
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #fff;
}
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }

/* ========== FLOOR/TREADMILL TOGGLE ========== */
.toggle-section { background: var(--bg); }
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 48px;
}
.toggle-btn {
  padding: 16px 40px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  border: 2px solid var(--border);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.toggle-btn:first-child { border-right: none; }
.toggle-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.toggle-btn:hover:not(.active) { border-color: var(--text-muted); color: #fff; }
.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}
.toggle-panel { display: none; animation: fadeInUp 0.4s ease; }
.toggle-panel.active { display: block; }
.toggle-panel h3 {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
}
.toggle-panel p {
  color: var(--text-muted);
  font-size: 1.05rem;
  line-height: 1.8;
}
.toggle-panel .toggle-icon {
  font-size: 3rem;
  color: var(--red);
  margin-bottom: 20px;
}

/* ========== INSTRUCTOR GRID ========== */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  animation: fadeInUp 0.4s ease;
}
.instructor-card:hover { border-color: var(--red); transform: translateY(-4px); }
.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-card), rgba(230,57,70,0.1));
  display: flex;
  align-items: center;
  justify-content: center;
}
.instructor-photo i {
  font-size: 4rem;
  color: var(--red);
  opacity: 0.5;
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
}
.instructor-info .location {
  color: var(--text-muted);
  font-size: 0.85rem;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.instructor-info .location i { color: var(--red); font-size: 0.9rem; }
.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--red);
  font-weight: 600;
  transition: color var(--transition);
}
.instructor-info .book-link:hover { color: #fff; }
.instructor-card.hidden { display: none; }

/* ========== FAQ ACCORDION ========== */
.faq-list { max-width: 780px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: #fff;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  text-align: left;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question i {
  font-size: 1.2rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.active .faq-question i { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p {
  padding: 0 0 24px;
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ========== DIGITAL FEATURES ========== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 32px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 40px 32px;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--red); transform: translateY(-4px); }
.feature-card .feature-icon {
  font-size: 2.2rem;
  color: var(--red);
  margin-bottom: 20px;
}
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
}
.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* ========== CTA SECTION (reusable) ========== */
.cta-section {
  text-align: center;
  padding: 80px 0;
}
.cta-section h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 28px;
}

/* ========== ANIMATIONS ========== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-utility { display: none; }
  .hamburger { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 24px;
    gap: 16px;
    border-bottom: 1px solid var(--border);
  }
  .nav-utility.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 0 24px 24px;
    gap: 12px;
  }
  .community-inner { grid-template-columns: 1fr; gap: 40px; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  section { padding: 70px 0; }
  .hero { min-height: 70vh; }
  .hero-sm { min-height: 40vh; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .btn { width: 100%; max-width: 320px; justify-content: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { width: 100%; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .carousel-btn { width: 40px; height: 40px; }
  .toggle-controls { flex-direction: column; align-items: center; }
  .toggle-btn { width: 100%; max-width: 300px; }
  .toggle-btn:first-child { border-right: 2px solid var(--border); border-bottom: none; }
  .filter-controls { gap: 8px; }
  .filter-btn { padding: 8px 16px; font-size: 0.75rem; }
  .schedule-table th, .schedule-table td { padding: 14px 16px; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .way-card { padding: 32px 24px; }
  .hero h1 { letter-spacing: 1px; }
}

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B71C1C;
  --bg: #111;
  --bg-card: #1a1a1a;
  --bg-card-hover: #222;
  --bg-surface: #161616;
  --text: #fff;
  --text-muted: #aaa;
  --text-dim: #777;
  --border: #2a2a2a;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --max-width: 1200px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button, input, select { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ========== TOP BAR ========== */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.5px;
}
.top-bar a {
  color: #fff;
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 600;
}

/* ========== NAV ========== */
.nav {
  background: rgba(17,17,17,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
}
.nav-logo span { color: #fff; }
.nav-links { display: flex; gap: 28px; align-items: center; }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: #fff; }
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--red);
  transition: width var(--transition);
}
.nav-links a:hover::after, .nav-links a.active::after { width: 100%; }
.nav-utility { display: flex; gap: 16px; align-items: center; }
.nav-utility a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  transition: color var(--transition);
}
.nav-utility a:hover { color: #fff; }
.btn-nav {
  background: var(--red);
  color: #fff !important;
  padding: 10px 20px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform 0.15s;
}
.btn-nav:hover { background: var(--red-dark); transform: translateY(-1px); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
}
.hamburger span {
  width: 24px;
  height: 2px;
  background: #fff;
  transition: var(--transition);
}

/* ========== HERO ========== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: linear-gradient(135deg, #111 0%, #1a0a0a 50%, #111 100%);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230,57,70,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}
.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 3px;
  margin-bottom: 20px;
}
.hero h1 .highlight { color: var(--red); }
.hero p {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 36px;
  line-height: 1.7;
}
.hero-ctas { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.hero-sm { min-height: 50vh; }
.hero-sm h1 { font-size: clamp(2rem, 5vw, 3.5rem); }

/* ========== BUTTONS ========== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 16px 36px;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.btn-primary { background: var(--red); color: #fff; }
.btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); box-shadow: 0 8px 30px rgba(230,57,70,0.3); }
.btn-outline { background: transparent; color: #fff; border: 2px solid #fff; }
.btn-outline:hover { background: #fff; color: #111; }
.btn-large { padding: 20px 48px; font-size: 1.15rem; }
.btn-sm { padding: 12px 24px; font-size: 0.85rem; }

/* ========== SECTIONS ========== */
section { padding: 100px 0; }
.section-header {
  text-align: center;
  margin-bottom: 60px;
}
.section-header h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto;
  line-height: 1.7;
}
.red-line {
  width: 60px;
  height: 3px;
  background: var(--red);
  margin: 20px auto;
}

/* ========== COMMUNITY PROMO ========== */
.community-promo {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.community-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.community-text h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 20px;
}
.community-text p {
  color: var(--text-muted);
  font-size: 1.05rem;
  line-height: 1.8;
  margin-bottom: 32px;
}
.community-visual {
  background: linear-gradient(135deg, var(--bg-card), rgba(230,57,70,0.1));
  border: 1px solid var(--border);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2rem;
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 4px;
}

/* ========== TWO WAYS ========== */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: var(--red); transform: translateY(-4px); }
.way-card .icon-wrap {
  width: 64px;
  height: 64px;
  background: rgba(230,57,70,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  font-size: 1.5rem;
  color: var(--red);
}
.way-card h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
}
.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 28px;
}

/* ========== STUDIO EXPERIENCE ========== */
.studio-exp {
  background: linear-gradient(180deg, var(--bg) 0%, #1a0a0a 50%, var(--bg) 100%);
  text-align: center;
}
.studio-exp .cta-text {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--text-muted);
  margin-bottom: 24px;
}

/* ========== FREE TRIAL ========== */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 0%, rgba(0,0,0,0.2) 100%);
  pointer-events: none;
}
.free-trial h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 4px;
  margin-bottom: 32px;
  position: relative;
}
.free-trial .btn {
  position: relative;
  background: #fff;
  color: var(--red);
}
.free-trial .btn:hover {
  background: #111;
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* ========== CAROUSEL ========== */
.carousel-section { overflow: hidden; background: var(--bg-surface); }
.carousel-wrap { position: relative; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/7;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  text-align: center;
  padding: 40px;
}
.carousel-slide h3 {
  font-family: var(--font-heading);
  font-size: 2rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 12px;
}
.carousel-slide p { color: var(--text-muted); font-size: 1.1rem; }
.carousel-slide:nth-child(1) { background: linear-gradient(135deg, #1a1a1a, rgba(230,57,70,0.15)); }
.carousel-slide:nth-child(2) { background: linear-gradient(135deg, rgba(230,57,70,0.1), #1a1a1a); }
.carousel-slide:nth-child(3) { background: linear-gradient(135deg, #1a1a1a, rgba(230,57,70,0.2)); }
.carousel-slide:nth-child(4) { background: linear-gradient(135deg, rgba(230,57,70,0.08), #1a1a1a); }
.carousel-icon {
  font-size: 4rem;
  color: var(--red);
  margin-bottom: 20px;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 52px;
  height: 52px;
  background: rgba(17,17,17,0.8);
  border: 1px solid var(--border);
  color: #fff;
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  z-index: 10;
}
.carousel-btn:hover { background: var(--red); border-color: var(--red); }
.carousel-btn.prev { left: 20px; }
.carousel-btn.next { right: 20px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  padding: 24px 0;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* ========== NEWSLETTER ========== */
.newsletter {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: 80px 0;
}
.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 12px;
}
.newsletter p {
  color: var(--text-muted);
  margin-bottom: 28px;
  line-height: 1.7;
}
.newsletter-form {
  display: flex;
  gap: 12px;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: #fff;
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form button {
  padding: 14px 28px;
  background: var(--red);
  color: #fff;
  border: none;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-msg {
  margin-top: 12px;
  font-size: 0.85rem;
  min-height: 20px;
}
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: var(--red); }

/* ========== FOOTER ========== */
.footer {
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 50px;
}
.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 20px;
  color: var(--red);
}
.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 5px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.country-select {
  padding: 10px 14px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.85rem;
  outline: none;
  width: 100%;
  margin-top: 8px;
  cursor: pointer;
}
.country-select:focus { border-color: var(--red); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer-bottom p {
  color: var(--text-dim);
  font-size: 0.8rem;
}
.footer-socials { display: flex; gap: 16px; }
.footer-socials a {
  color: var(--text-muted);
  font-size: 1.2rem;
  transition: color var(--transition);
}
.footer-socials a:hover { color: var(--red); }

/* ========== METHOD OVERVIEW ========== */
.method-overview { background: var(--bg-surface); }
.method-text {
  max-width: 750px;
  margin: 0 auto;
  text-align: center;
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.9;
}

/* ========== WEEKLY SCHEDULE ========== */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  max-width: 700px;
  margin: 0 auto;
}
.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td {
  font-size: 0.95rem;
  color: var(--text-muted);
}
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #fff;
}
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }

/* ========== FLOOR/TREADMILL TOGGLE ========== */
.toggle-section { background: var(--bg); }
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 48px;
}
.toggle-btn {
  padding: 16px 40px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  border: 2px solid var(--border);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.toggle-btn:first-child { border-right: none; }
.toggle-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.toggle-btn:hover:not(.active) { border-color: var(--text-muted); color: #fff; }
.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}
.toggle-panel { display: none; animation: fadeInUp 0.4s ease; }
.toggle-panel.active { display: block; }
.toggle-panel h3 {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
}
.toggle-panel p {
  color: var(--text-muted);
  font-size: 1.05rem;
  line-height: 1.8;
}
.toggle-panel .toggle-icon {
  font-size: 3rem;
  color: var(--red);
  margin-bottom: 20px;
}

/* ========== INSTRUCTOR GRID ========== */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  animation: fadeInUp 0.4s ease;
}
.instructor-card:hover { border-color: var(--red); transform: translateY(-4px); }
.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-card), rgba(230,57,70,0.1));
  display: flex;
  align-items: center;
  justify-content: center;
}
.instructor-photo i {
  font-size: 4rem;
  color: var(--red);
  opacity: 0.5;
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
}
.instructor-info .location {
  color: var(--text-muted);
  font-size: 0.85rem;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.instructor-info .location i { color: var(--red); font-size: 0.9rem; }
.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--red);
  font-weight: 600;
  transition: color var(--transition);
}
.instructor-info .book-link:hover { color: #fff; }
.instructor-card.hidden { display: none; }

/* ========== FAQ ACCORDION ========== */
.faq-list { max-width: 780px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: #fff;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  text-align: left;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question i {
  font-size: 1.2rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.active .faq-question i { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p {
  padding: 0 0 24px;
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ========== DIGITAL FEATURES ========== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 32px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 40px 32px;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--red); transform: translateY(-4px); }
.feature-card .feature-icon {
  font-size: 2.2rem;
  color: var(--red);
  margin-bottom: 20px;
}
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
}
.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* ========== CTA SECTION (reusable) ========== */
.cta-section {
  text-align: center;
  padding: 80px 0;
}
.cta-section h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 28px;
}

/* ========== ANIMATIONS ========== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-utility { display: none; }
  .hamburger { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 24px;
    gap: 16px;
    border-bottom: 1px solid var(--border);
  }
  .nav-utility.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 0 24px 24px;
    gap: 12px;
  }
  .community-inner { grid-template-columns: 1fr; gap: 40px; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  section { padding: 70px 0; }
  .hero { min-height: 70vh; }
  .hero-sm { min-height: 40vh; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .btn { width: 100%; max-width: 320px; justify-content: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { width: 100%; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .carousel-btn { width: 40px; height: 40px; }
  .toggle-controls { flex-direction: column; align-items: center; }
  .toggle-btn { width: 100%; max-width: 300px; }
  .toggle-btn:first-child { border-right: 2px solid var(--border); border-bottom: none; }
  .filter-controls { gap: 8px; }
  .filter-btn { padding: 8px 16px; font-size: 0.75rem; }
  .schedule-table th, .schedule-table td { padding: 14px 16px; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .way-card { padding: 32px 24px; }
  .hero h1 { letter-spacing: 1px; }
}

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #E63946;
  --red-dark: #B71C1C;
  --bg: #111;
  --bg-card: #1a1a1a;
  --bg-card-hover: #222;
  --bg-surface: #161616;
  --text: #fff;
  --text-muted: #aaa;
  --text-dim: #777;
  --border: #2a2a2a;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --max-width: 1200px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button, input, select { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ========== TOP BAR ========== */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.5px;
}
.top-bar a {
  color: #fff;
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 600;
}

/* ========== NAV ========== */
.nav {
  background: rgba(17,17,17,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
}
.nav-logo span { color: #fff; }
.nav-links { display: flex; gap: 28px; align-items: center; }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: #fff; }
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--red);
  transition: width var(--transition);
}
.nav-links a:hover::after, .nav-links a.active::after { width: 100%; }
.nav-utility { display: flex; gap: 16px; align-items: center; }
.nav-utility a {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  transition: color var(--transition);
}
.nav-utility a:hover { color: #fff; }
.btn-nav {
  background: var(--red);
  color: #fff !important;
  padding: 10px 20px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform 0.15s;
}
.btn-nav:hover { background: var(--red-dark); transform: translateY(-1px); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
}
.hamburger span {
  width: 24px;
  height: 2px;
  background: #fff;
  transition: var(--transition);
}

/* ========== HERO ========== */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  background: linear-gradient(135deg, #111 0%, #1a0a0a 50%, #111 100%);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230,57,70,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}
.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.05;
  letter-spacing: 3px;
  margin-bottom: 20px;
}
.hero h1 .highlight { color: var(--red); }
.hero p {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 36px;
  line-height: 1.7;
}
.hero-ctas { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.hero-sm { min-height: 50vh; }
.hero-sm h1 { font-size: clamp(2rem, 5vw, 3.5rem); }

/* ========== BUTTONS ========== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 16px 36px;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.btn-primary { background: var(--red); color: #fff; }
.btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); box-shadow: 0 8px 30px rgba(230,57,70,0.3); }
.btn-outline { background: transparent; color: #fff; border: 2px solid #fff; }
.btn-outline:hover { background: #fff; color: #111; }
.btn-large { padding: 20px 48px; font-size: 1.15rem; }
.btn-sm { padding: 12px 24px; font-size: 0.85rem; }

/* ========== SECTIONS ========== */
section { padding: 100px 0; }
.section-header {
  text-align: center;
  margin-bottom: 60px;
}
.section-header h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 650px;
  margin: 0 auto;
  line-height: 1.7;
}
.red-line {
  width: 60px;
  height: 3px;
  background: var(--red);
  margin: 20px auto;
}

/* ========== COMMUNITY PROMO ========== */
.community-promo {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.community-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.community-text h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 20px;
}
.community-text p {
  color: var(--text-muted);
  font-size: 1.05rem;
  line-height: 1.8;
  margin-bottom: 32px;
}
.community-visual {
  background: linear-gradient(135deg, var(--bg-card), rgba(230,57,70,0.1));
  border: 1px solid var(--border);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 2rem;
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 4px;
}

/* ========== TWO WAYS ========== */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 48px 40px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: var(--red); transform: translateY(-4px); }
.way-card .icon-wrap {
  width: 64px;
  height: 64px;
  background: rgba(230,57,70,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  font-size: 1.5rem;
  color: var(--red);
}
.way-card h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
}
.way-card p {
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 28px;
}

/* ========== STUDIO EXPERIENCE ========== */
.studio-exp {
  background: linear-gradient(180deg, var(--bg) 0%, #1a0a0a 50%, var(--bg) 100%);
  text-align: center;
}
.studio-exp .cta-text {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--text-muted);
  margin-bottom: 24px;
}

/* ========== FREE TRIAL ========== */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 0%, rgba(0,0,0,0.2) 100%);
  pointer-events: none;
}
.free-trial h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 4px;
  margin-bottom: 32px;
  position: relative;
}
.free-trial .btn {
  position: relative;
  background: #fff;
  color: var(--red);
}
.free-trial .btn:hover {
  background: #111;
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* ========== CAROUSEL ========== */
.carousel-section { overflow: hidden; background: var(--bg-surface); }
.carousel-wrap { position: relative; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  will-change: transform;
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/7;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  text-align: center;
  padding: 40px;
}
.carousel-slide h3 {
  font-family: var(--font-heading);
  font-size: 2rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 12px;
}
.carousel-slide p { color: var(--text-muted); font-size: 1.1rem; }
.carousel-slide:nth-child(1) { background: linear-gradient(135deg, #1a1a1a, rgba(230,57,70,0.15)); }
.carousel-slide:nth-child(2) { background: linear-gradient(135deg, rgba(230,57,70,0.1), #1a1a1a); }
.carousel-slide:nth-child(3) { background: linear-gradient(135deg, #1a1a1a, rgba(230,57,70,0.2)); }
.carousel-slide:nth-child(4) { background: linear-gradient(135deg, rgba(230,57,70,0.08), #1a1a1a); }
.carousel-icon {
  font-size: 4rem;
  color: var(--red);
  margin-bottom: 20px;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 52px;
  height: 52px;
  background: rgba(17,17,17,0.8);
  border: 1px solid var(--border);
  color: #fff;
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  z-index: 10;
}
.carousel-btn:hover { background: var(--red); border-color: var(--red); }
.carousel-btn.prev { left: 20px; }
.carousel-btn.next { right: 20px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  padding: 24px 0;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* ========== NEWSLETTER ========== */
.newsletter {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: 80px 0;
}
.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 12px;
}
.newsletter p {
  color: var(--text-muted);
  margin-bottom: 28px;
  line-height: 1.7;
}
.newsletter-form {
  display: flex;
  gap: 12px;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: #fff;
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-form button {
  padding: 14px 28px;
  background: var(--red);
  color: #fff;
  border: none;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-msg {
  margin-top: 12px;
  font-size: 0.85rem;
  min-height: 20px;
}
.newsletter-msg.success { color: #4caf50; }
.newsletter-msg.error { color: var(--red); }

/* ========== FOOTER ========== */
.footer {
  background: #0a0a0a;
  border-top: 1px solid var(--border);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 50px;
}
.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 20px;
  color: var(--red);
}
.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 5px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: #fff; }
.country-select {
  padding: 10px 14px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.85rem;
  outline: none;
  width: 100%;
  margin-top: 8px;
  cursor: pointer;
}
.country-select:focus { border-color: var(--red); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.footer-bottom p {
  color: var(--text-dim);
  font-size: 0.8rem;
}
.footer-socials { display: flex; gap: 16px; }
.footer-socials a {
  color: var(--text-muted);
  font-size: 1.2rem;
  transition: color var(--transition);
}
.footer-socials a:hover { color: var(--red); }

/* ========== METHOD OVERVIEW ========== */
.method-overview { background: var(--bg-surface); }
.method-text {
  max-width: 750px;
  margin: 0 auto;
  text-align: center;
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.9;
}

/* ========== WEEKLY SCHEDULE ========== */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  max-width: 700px;
  margin: 0 auto;
}
.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid var(--border);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td {
  font-size: 0.95rem;
  color: var(--text-muted);
}
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #fff;
}
.schedule-table tr:hover td { background: rgba(230,57,70,0.05); }

/* ========== FLOOR/TREADMILL TOGGLE ========== */
.toggle-section { background: var(--bg); }
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 48px;
}
.toggle-btn {
  padding: 16px 40px;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
  border: 2px solid var(--border);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.toggle-btn:first-child { border-right: none; }
.toggle-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.toggle-btn:hover:not(.active) { border-color: var(--text-muted); color: #fff; }
.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}
.toggle-panel { display: none; animation: fadeInUp 0.4s ease; }
.toggle-panel.active { display: block; }
.toggle-panel h3 {
  font-family: var(--font-heading);
  font-size: 1.6rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
}
.toggle-panel p {
  color: var(--text-muted);
  font-size: 1.05rem;
  line-height: 1.8;
}
.toggle-panel .toggle-icon {
  font-size: 3rem;
  color: var(--red);
  margin-bottom: 20px;
}

/* ========== INSTRUCTOR GRID ========== */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition);
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  animation: fadeInUp 0.4s ease;
}
.instructor-card:hover { border-color: var(--red); transform: translateY(-4px); }
.instructor-photo {
  aspect-ratio: 1;
  background: linear-gradient(135deg, var(--bg-card), rgba(230,57,70,0.1));
  display: flex;
  align-items: center;
  justify-content: center;
}
.instructor-photo i {
  font-size: 4rem;
  color: var(--red);
  opacity: 0.5;
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
}
.instructor-info .location {
  color: var(--text-muted);
  font-size: 0.85rem;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.instructor-info .location i { color: var(--red); font-size: 0.9rem; }
.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--red);
  font-weight: 600;
  transition: color var(--transition);
}
.instructor-info .book-link:hover { color: #fff; }
.instructor-card.hidden { display: none; }

/* ========== FAQ ACCORDION ========== */
.faq-list { max-width: 780px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  color: #fff;
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  cursor: pointer;
  text-align: left;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question i {
  font-size: 1.2rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.active .faq-question i { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p {
  padding: 0 0 24px;
  color: var(--text-muted);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ========== DIGITAL FEATURES ========== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 32px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 40px 32px;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--red); transform: translateY(-4px); }
.feature-card .feature-icon {
  font-size: 2.2rem;
  color: var(--red);
  margin-bottom: 20px;
}
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
}
.feature-card p {
  color: var(--text-muted);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* ========== CTA SECTION (reusable) ========== */
.cta-section {
  text-align: center;
  padding: 80px 0;
}
.cta-section h2 {
  font-family: var(--font-heading);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 28px;
}

/* ========== ANIMATIONS ========== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-utility { display: none; }
  .hamburger { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 24px;
    gap: 16px;
    border-bottom: 1px solid var(--border);
  }
  .nav-utility.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    background: rgba(17,17,17,0.98);
    padding: 0 24px 24px;
    gap: 12px;
  }
  .community-inner { grid-template-columns: 1fr; gap: 40px; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  section { padding: 70px 0; }
  .hero { min-height: 70vh; }
  .hero-sm { min-height: 40vh; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .btn { width: 100%; max-width: 320px; justify-content: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { width: 100%; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .carousel-btn { width: 40px; height: 40px; }
  .toggle-controls { flex-direction: column; align-items: center; }
  .toggle-btn { width: 100%; max-width: 300px; }
  .toggle-btn:first-child { border-right: 2px solid var(--border); border-bottom: none; }
  .filter-controls { gap: 8px; }
  .filter-btn { padding: 8px 16px; font-size: 0.75rem; }
  .schedule-table th, .schedule-table td { padding: 14px 16px; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .way-card { padding: 32px 24px; }
  .hero h1 { letter-spacing: 1px; }
}

